  const phoneNumber = rawPhone.replace(/^\+/, ''); // "201099160912"
  const senderJid = phoneNumber ? `${phoneNumber}@s.whatsapp.net` : '';

  // 2. Sender display name (the customer)
  const senderName = conversation.participantName || sender.name || '';

  // 3. Timestamp — ISO 8601 string, offset to UTC+3
