={{
  (() => {
    const bookings = $('Execute a SQL query7').all().map(item => item.json);
    const payment = $('Code in JavaScript13').first().json;
    const first = bookings[0] || {};

    // المبلغ المدفوع من Paymob بالريال
    const paidAmount = Number(payment.paidAmount) || 0;
    // عربون الفرد من جدول الخدمات أو الحجز
    const unitDeposit = Number(first.unit_deposit) || Number(first.deposit_amount) || 50;
    const bookingsCount = bookings.length;
    const paidBookingsCount = Math.floor(paidAmount / unitDeposit);

    // تنسيق التاريخ
    const dateFormatted = first.booking_date 
      ? new Date(first.booking_date).toLocaleDateString('ar-SA', { timeZone: 'UTC', weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })
      : '';

    // دالة مساعدة لتنسيق الوقت من booking_date المخزن
    const formatSlotTime = (dateStr, fallbackTime) => {
      if (!dateStr) return fallbackTime || '';
      const d = new Date(dateStr);
      const h = d.getUTCHours();
      const m = d.getUTCMinutes().toString().padStart(2, '0');
      const period = h >= 12 ? 'مساءً' : 'صباحاً';
      const h12 = (h % 12 || 12).toString().padStart(2, '0');
      return `${h12}:${m} ${period}`;
    };

    // تجميع أوقات وأكواد كل شخص في المجموعة
    const slotsDetails = bookings.map((b, idx) => {
      const timeText = formatSlotTime(b.booking_date, b.booking_time);
      const label = bookingsCount > 1 ? `• شخص ${idx + 1}: ` : '• الموعد: ';
      return `${label}${timeText} (كود الحجز: ${b.booking_code})`;
    }).join('\n');

    if (bookingsCount > 1) {
      return `أهلاً بكِ ${first.client_name} 🌸\nتم تأكيد حجزكم بنجاح في صالون نون ✨\n\n` +
        `💇 الخدمة: ${first.service_name}\n` +
        `👩🎨 الأخصائية: ${first.staff_name}\n` +
        `🏢 الفرع: ${first.branch_name}\n` +
        `📅 التاريخ: ${dateFormatted}\n` +
        `👥 عدد الأشخاص: ${bookingsCount}\n` +
        `💰 العربون المدفوع: ${paidAmount} ريال (تم سداد ${paidBookingsCount} حجز)\n\n` +
        `📋 تفاصيل المواعيد والأكواد:\n${slotsDetails}\n\n` +
        `ننتظر تشريفكم لنا ونتمنى لكم تجربة مميزة 💖`;
    } else {
      const singleTime = formatSlotTime(first.booking_date, first.booking_time);
      return `✅ تم تأكيد حجزكِ بنجاح يا ${first.client_name} 💄✨\n\n` +
        `💄 الخدمة: ${first.service_name}\n` +
        `👩🎨 الأخصائية: ${first.staff_name}\n` +
        `🏢 الفرع: ${first.branch_name}\n` +
        `📅 التاريخ: ${dateFormatted}\n` +
        `⏰ الوقت: ${singleTime}\n` +
        `💰 إجمالي السعر: ${first.service_price} ريال\n` +
        `💵 العربون المدفوع: ${paidAmount} ريال\n\n` +
        `🎟️ كود الحجز: ${first.booking_code}\n\n` +
        `شكرًا لاختياركِ لنا 🤍\nنتمنى لكِ تجربة جميلة ومميزة ✨`;
    }
  })()
}}
